type Env = { Bindings: { DB?: D1Database; STORE?: Store; ADMIN_USERNAME?: string; ADMIN_PASSWORD?: string; ASSETS?: { fetch: (request: Request) => Promise<Response> }; STATIC?: {fetch:(request:Request)=>Promise<Response>} } };
const app = new Hono<Env>();
const wrappedStores=new WeakMap<object,StructuredStore>();
const store = (c: any): Store | null => {const raw:Store|null=c.env?.STORE||(c.env?.DB?new D1Store(c.env.DB):null);if(!raw)return null;let wrapped=wrappedStores.get(raw as object);if(!wrapped){wrapped=new StructuredStore(raw);wrappedStores.set(raw as object,wrapped)}return wrapped};
type SubscriptionProfile = { id: string; name: string; urls: string[]; format: string; rulesUrl?: string };
