app.post('/api/subscribe', async c => {
  const db = store(c);
  if (!db) return c.json({ error: 'Database binding is missing' }, 503);
  const body = await readJson(c);
  if (!body.ok) return c.json({ error: 'Invalid JSON body' }, 400);
  const input=body.value as any, id=String(input.path||'').trim()||crypto.randomUUID();
  if(!validAggregatePath(id))return c.json({error:'Link path must use 3-128 letters, numbers, hyphens or underscores'},400);
  if(await db.get('aggregate:'+id)!==null)return c.json({error:'Link path already exists'},409);
  const created=await makeAggregateRecord(db,input,id,'public');
  if(!created.ok)return c.json({error:created.error},400);
  await db.put('aggregate:'+id,JSON.stringify(created.value));
  return c.json({id,url:publicUrl(c,'/api/'+id)},201);
});
app.get('/api/subscribe', async c => {
  const query = new URL(c.req.url).searchParams;
  const requested = requestedFormat(query);
  const urls = query.getAll('url');
  if (!urls.length) return c.json({ error: 'At least one source URL is required' }, 400);
  if (!requested && (c.req.header('accept') || '').includes('text/html')) {
    const db = store(c);
    if (!db) return c.json({ error: 'Database binding is missing' }, 503);
    const id = crypto.randomUUID();
    await db.put('aggregate:' + id, JSON.stringify({ id, owner:false, sources: urls, kind: 'public', backendId: BUILTIN_SUBAPI_ID }));
    return c.redirect(publicUrl(c,'/api/'+id), 302);
  }
  const format = requested || detectSubscriptionFormat(c.req.header('user-agent') || '') || 'base64';
  const request = new Request(new URL('/api/convert', c.req.url), {
    method: 'POST', headers: { 'content-type': 'application/json' },
    body: JSON.stringify({ urls, format, rulesUrl: query.get('rules') }),
  });
  return app.fetch(request, c.env);
});
function normHomeTitle(raw:any):{zh:string;en:string;fa:string}{
  const d={zh:'订阅转换',en:'Subscription Converter',fa:'تبدیل اشتراک'};
  let v:any=null;
  try{v=typeof raw==='string'?JSON.parse(raw):raw;}catch{v=null;}
  if(typeof v==='string'){d.zh=v.trim()||'订阅转换';return d;}
  if(v&&typeof v==='object'){
    if(String(v.zh||'').trim())d.zh=String(v.zh).trim();
    if(String(v.en||'').trim())d.en=String(v.en).trim();
    if(String(v.fa||'').trim())d.fa=String(v.fa).trim();
  }
  return d;
}
