app.post('/api/convert', async c => {
  let body: { url?: string; urls?: string[]; text?: string; format?: string; rulesUrl?: string; noAds?: string };
  try { body = await c.req.json(); } catch { return c.json({ error: 'Invalid JSON body' }, 400); }
  const sources = body.text ? [body.text] : [];
  const db=store(c);
  const assets=(c.env as any)?.ASSETS;
  const assetBase=new URL(c.req.url).origin+'/ACL4SSR/Clash/';
  const urls = [...(body.urls || []), ...(body.url ? [body.url] : [])];
  if (urls.length > 20) return c.json({ error: 'At most 20 upstreams are allowed' }, 400);
  const upstreams: URL[] = [];
  for (const raw of urls) {
    let url: URL;
    try { url = new URL(raw); } catch { return c.json({ error: `Invalid upstream URL: ${raw}` }, 400); }
    if (!['http:', 'https:'].includes(url.protocol)) return c.json({ error: 'Only HTTP(S) upstream URLs are allowed' }, 400);
    upstreams.push(url);
  }
  const fetched: Array<{ text: string } | { error: string }> = await Promise.all(upstreams.map(async url => {
    try {
      const response = await fetch(url, { signal: timeoutSignal(15000) });
      if (!response.ok) return { error: `Upstream ${url.host} returned ${response.status}` };
      return { text: await response.text() };
    } catch { return { error: `Could not fetch upstream: ${url.host}` }; }
  }));
  const failure = fetched.find(result => 'error' in result);
  if (failure && 'error' in failure) return c.json({ error: failure.error }, 502);
  sources.push(...fetched.flatMap(result => 'text' in result ? [result.text] : []));
  // Normalize upstream payloads: only decode when the body is not already recognizable plaintext.
  const normalized = sources.map(normalizeSubscription).join('\n');
  // Keep the legacy converter's server-side base64 intermediary while parsing only its decoded plaintext.
  const intermediate = encodeBase64(normalized);
  const excluded=String(body.noAds||'').split(/[\r\n,]+/).map(value=>value.trim().toLowerCase()).filter(Boolean);
  const nodes = dedupe(parseNodes(decodeBase64(intermediate))).filter(node=>!excluded.some(keyword=>node.name.toLowerCase().includes(keyword)));
  if (!nodes.length) return c.json({ error: 'No supported nodes found' }, 400);
  const format = (body.format || 'singbox').toLowerCase();
  try {
  if (format === 'clash') { if(!nodes.some(isMihomoCompatible))return c.json({error:'No nodes supported by Mihomo/Clash Meta for this input'},400);let rules; try { rules=await loadRules(db, body.rulesUrl, undefined, assets, assetBase); } catch(e) { return c.json({error:e instanceof Error?e.message:'Could not load rules'},502); } return c.text(clash(nodes,rules), 200, { 'content-type': 'text/plain; charset=utf-8' }); }
  if (format === 'base64' || format === 'v2rayn') return c.text(encodeBase64(nodes.map(n => n.raw || `${n.type}://${n.server}:${n.port}#${encodeURIComponent(n.name)}`).join('\n')), 200, { 'content-type': 'text/plain; charset=utf-8' });
  if (format === 'singbox' || format === 'sing-box') {
    if (!nodes.some(isSingboxCompatible)) return c.json({ error: 'No input nodes are compatible with the current sing-box outbound schema (currently unsupported: XHTTP, VLESS encryption, SSR, Mieru, TUIC v4, Snell v3)' }, 400);
    let rules;
    try { rules = await loadRules(db, body.rulesUrl, undefined, assets, assetBase); }
    catch (e) { return c.json({ error: e instanceof Error ? e.message : 'Could not load rules' }, 502); }
    return c.json(singbox(nodes, rules));
  }
  if (format === 'surge' || format === 'loon' || format === 'quanx' || format === 'quantumultx' || format === 'quantumult-x') {
    const compatible = format === 'surge' ? isSurgeCompatible : format === 'loon' ? isLoonCompatible : isQuanxCompatible;
    if (!nodes.some(compatible)) return c.json({ error: `No nodes supported by ${format}` }, 400);
    let rules;
    try { rules = await loadRules(db, body.rulesUrl, undefined, assets, assetBase); }
    catch (e) { return c.json({ error: e instanceof Error ? e.message : 'Could not load rules' }, 502); }
    const renderer = format === 'surge' ? surge : format === 'loon' ? loon : quanx;
    return c.text(renderer(nodes, rules), 200, { 'content-type': 'text/plain; charset=utf-8' });
  }
  return c.json({ error: `Unsupported output format: ${format}` }, 400);
  } catch(e){ return c.json({ error: 'Conversion failed: ' + (e instanceof Error ? e.message : String(e)) }, 500); }
});
