  'quanx': 'quanx', 'quantumultx': 'quanx', 'quantumult-x': 'quanx',
  'loon': 'loon',
  'singbox': 'singbox', 'sing-box': 'singbox',
  'base64': 'base64', 'v2ray': 'base64', 'v2rayn': 'base64', 'mixed': 'base64',
