function decodeSubscription(input: string): string {
  const value = input.trim().replace(/\s+/g, '');
  if (!value || !/^[A-Za-z0-9+/=_-]+$/.test(value)) return input;
  try { const decoded = atob(value.replace(/-/g, '+').replace(/_/g, '/')); const bytes = Uint8Array.from(decoded, c => c.charCodeAt(0)); const text = new TextDecoder().decode(bytes); return /^[a-z][a-z0-9+.-]*:\/\//im.test(text) ? text : input; } catch { return input; }
}
