  const serialized=await db.get('config:backends');if(!serialized)return 'Selected conversion backend does not exist';
  try { const backends=JSON.parse(serialized) as Array<{id:string;apiUrl:string;configUrl?:string}>;return backends.some(item=>item.id===id&&isHttpUrl(item.apiUrl))?null:'Selected conversion backend does not exist'; }
