  if (query.has('sb') || query.has('singbox')) return 'singbox';
  if (query.has('surge')) return 'surge';
  if (query.has('quanx')) return 'quanx';
  if (query.has('loon')) return 'loon';
  if (query.has('b64')) return 'base64';
  return null;
