  if (/quantumult\s*x|quantumultx|quantumult/i.test(userAgent)) return 'quanx';
  if (/\bsurge\b/i.test(userAgent)) return 'surge';
  if (/\bloon\b/i.test(userAgent)) return 'loon';
  if (/v2rayn|v2rayng|nekoray|shadowrocket|stash|hiddify|nekobox/i.test(userAgent)) return 'base64';
